--
-- Table structure for table `provider_payments`
--

DROP TABLE IF EXISTS `provider_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `provider_payments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `provider_invoices_id` bigint(20) unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `cheque_number` int(11) DEFAULT NULL,
  `payment_account` bigint(20) unsigned NOT NULL,
  `depositing_date` date DEFAULT NULL,
  `deposited_check` enum('0','1') NOT NULL DEFAULT '0',
  `note` text DEFAULT NULL,
  `expense_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `payment_account` (`payment_account`),
  KEY `fk_provider_payments_expenses` (`expense_id`),
  KEY `provider_payments_provider_invoices_id_foreign` (`provider_invoices_id`),
  CONSTRAINT `fk_expense_id` FOREIGN KEY (`expense_id`) REFERENCES `expenses` (`id`),
  CONSTRAINT `fk_payment_acc` FOREIGN KEY (`payment_account`) REFERENCES `cash_bank_accounts` (`id`),
  CONSTRAINT `fk_provider_invoi_id` FOREIGN KEY (`provider_invoices_id`) REFERENCES `provider_invoices` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=337 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

