--
-- Table structure for table `quotations`
--

DROP TABLE IF EXISTS `quotations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quotations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` text DEFAULT 'N/A',
  `customer_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `extra_discount` text NOT NULL DEFAULT '0',
  `quota_reference` varchar(255) DEFAULT NULL,
  `status` text NOT NULL DEFAULT 'En_préparation',
  `worksite_id` bigint(20) unsigned DEFAULT NULL,
  `type` enum('quotation','invoice') DEFAULT NULL,
  `taxes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '["1","2"]' CHECK (json_valid(`taxes`)),
  `invoicing_date` date DEFAULT NULL,
  `invoice_reference` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quotation_client` (`customer_id`),
  KEY `quotations_worksite_id_foreign` (`worksite_id`),
  CONSTRAINT `fk_customer_id_quot` FOREIGN KEY (`customer_id`) REFERENCES `contacts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

